import { afterEach, describe, expect, it, vi } from "vitest";
import {
  audioPacket,
  makePipelinePlayer,
  packetRun,
  videoPacket,
} from "../helpers/pipeline-player";

// dist/wasm/movi.js is generated by build:wasm (Docker/4090) and is absent in
// the unit-test CI job (dist/ is gitignored). MoviPlayer's module graph imports
// it eagerly via FFmpegLoader; this test never loads/runs the WASM, so stub the
// module so importing the player graph resolves without the built artifact.
vi.mock("../../dist/wasm/movi.js", () => ({ default: vi.fn(async () => ({})) }));

vi.mock("dashjs", () => ({ MediaPlayer: vi.fn() }));
vi.mock("shaka-player/dist/shaka-player.compiled", () => ({
  default: {
    Player: { isBrowserSupported: vi.fn(() => false) },
    polyfill: { installAll: vi.fn() },
    net: { NetworkingEngine: { RequestType: { LICENSE: 1 } } },
  },
}));

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("rebuffer unlock", () => {
  /**
   * Black-box regression (real OpenList, headless Chrome, HEVC Main10 + FLAC):
   * a rebuffer is exactly when the audio cushion CANNOT drain — the renderer
   * is suspended and the clock is paused, so whatever `audioBuffered` was at
   * the stall is what it stays. When that cushion gated every read, the
   * player deadlocked: no reads, so no frame; no frame, so no resume; no
   * resume, so no drain. The observed run had 8.6s of audio buffered against
   * a 5s target and never left "buffering" — `media clock rate 0.340 during
   * steady playback`.
   *
   * With per-stream queues a full audio side has no say over the video's
   * reads: its packets wait in their own queue, and the empty video queue is
   * reason enough to read.
   */
  it("reads on while a rebuffer has no video at all, however far ahead audio got", async () => {
    const f = await makePipelinePlayer({
      state: "buffering",
      audioBuffered: 8.6,
      rendererQueue: 0,
      queuedAudio: packetRun((t) => audioPacket(t), 10, 16, 0.02),
    });
    await f.tick();
    expect(f.readPacket).toHaveBeenCalled();
    expect(f.audioDecode).not.toHaveBeenCalled();
  }, 20_000);

  it("still lets audio's cushion stop audio — and full queues stop the reads — when video is playing normally", async () => {
    const f = await makePipelinePlayer({
      audioBuffered: 8.6,
      rendererQueue: 30,
      video: { isSoftware: false, worker: false, queueSize: 31 },
      queuedVideo: packetRun((t) => videoPacket(t), 10, 16, 1 / 24),
      queuedAudio: packetRun((t) => audioPacket(t), 10, 16, 0.02),
    });
    await f.tick();
    // Not a rebuffer: playing, with decoded frames in hand. The cushion is over
    // target, so audio waits in its queue — that ceiling is the whole point —
    // and with both queues past their readahead there is nothing to read for.
    expect(f.audioDecode).not.toHaveBeenCalled();
    expect(f.readPacket).not.toHaveBeenCalled();
  }, 20_000);
});
